const $=id=>document.getElementById(id);let data;const avg=(rows,key)=>rows.reduce((s,r)=>s+r[key],0)/rows.length;const fixed=n=>Number.isFinite(n)?n.toFixed(1):'—';const plus=n=>(n>0?'+':'')+fixed(n);const months=['10','11','12','01','02','03','04'];const monthNames=['Oct','Nov','Dec','Jan','Feb','Mar','Apr'];
function selected(){return data.games.filter(g=>($('month').value==='all'||g.date.slice(5,7)===$('month').value)&&($('venue').value==='All venues'||g.venue===$('venue').value))}
function team(){const rows=selected(),w=rows.filter(g=>g.result==='W').length,margin=avg(rows,'points')-avg(rows,'allowed');$('scope').textContent=`${rows.length} games selected`;$('kpis').innerHTML=[['Win–loss record',`${w}<span style="color:#6b7d94">–${rows.length-w}</span>`,`${fixed(w/rows.length*100)}% win rate`],['Points per game',fixed(avg(rows,'points')),'Scoring output'],['Opponent points',fixed(avg(rows,'allowed')),'Points allowed per game'],['Average margin',plus(margin),'Points per game differential']].map(([a,b,c])=>`<div class="kpi"><div class="kpi-label">${a}<span>↗</span></div><strong>${b}</strong><small>${c}</small></div>`).join('');
const W=650,H=235,left=32,top=16,bottom=205,x=i=>left+i*(W-left-15)/Math.max(1,rows.length-1),y=n=>bottom-(n-70)/(160-70)*(bottom-top);let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Game-by-game points scored and allowed"><defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#4ba8ff" stop-opacity=".18"/><stop offset="1" stop-color="#4ba8ff" stop-opacity="0"/></linearGradient></defs>`;for(let n=80;n<=160;n+=20)svg+=`<line x1="${left}" x2="640" y1="${y(n)}" y2="${y(n)}" stroke="#26354a" stroke-dasharray="3 5"/><text x="0" y="${y(n)+4}">${n}</text>`;let path=rows.map((g,i)=>`${i?'L':'M'}${x(i)},${y(g.points)}`).join(' ');svg+=`<path d="${path} L${x(rows.length-1)},${bottom} L${left},${bottom}Z" fill="url(#fill)"/>`;for(const [key,color] of [['allowed','#ff8b42'],['points','#4ba8ff']]){svg+=`<polyline points="${rows.map((g,i)=>`${x(i)},${y(g[key])}`).join(' ')}" fill="none" stroke="${color}" stroke-width="2"/>`;rows.forEach((g,i)=>{svg+=`<circle cx="${x(i)}" cy="${y(g[key])}" r="4" fill="${color}" fill-opacity="${rows.length===1?1:.05}"><title>${g.date} · ${g.venue} vs ${g.opponent}: OKC ${g.points}, opponent ${g.allowed}</title></circle>`})}rows.forEach((g,i)=>{if(i===0||i===rows.length-1||i%Math.max(1,Math.ceil(rows.length/6))===0)svg+=`<text x="${x(i)}" y="228" text-anchor="middle">${g.date.slice(5).replace('-','/')}</text>`});$('trend').innerHTML=rows.length?svg+'</svg>':'<p style="padding:60px 0;text-align:center">No games match these filters.</p>';
$('margins').innerHTML=months.map((m,i)=>{let rr=data.games.filter(g=>g.date.slice(5,7)===m&&($('venue').value==='All venues'||g.venue===$('venue').value)),v=avg(rr,'points')-avg(rr,'allowed');return `<div class="margin-row"><span>${monthNames[i]}</span><div class="bar-track"><div class="bar-fill" style="width:${(Number.isFinite(v)?Math.min(100,Math.abs(v)/30*100):0)}%;background:${m===$('month').value?'#ff8b42':'#4ba8ff'}"></div></div><b>${plus(v)}</b></div>`}).join('');$('insight-title').textContent=`${fixed(w/rows.length*100)}% wins. ${plus(margin)} points of separation.`;$('insight-text').textContent=`Across these ${rows.length} games, OKC scored ${fixed(avg(rows,'points'))} and allowed ${fixed(avg(rows,'allowed'))} points per game. Scoring margin describes performance; it does not isolate player impact.`;if(!rows.length){$('insight-title').textContent='No games in this selection.';$('insight-text').textContent='Choose another month or reset the filters.'}games()}
function games(){const rows=selected().filter(g=>$('result').value==='all'||g.result===$('result').value);$('gamelog').innerHTML=rows.slice().reverse().map(g=>`<tr><td>${g.date}</td><td>${g.opponent}</td><td>${g.venue}</td><td><span class="pill ${g.result==='L'?'loss':''}">${g.result}</span></td><td>${g.points}</td><td>${g.allowed}</td><td class="${g.result==='W'?'positive':''}">${g.points-g.allowed>0?'+':''}${g.points-g.allowed}</td></tr>`).join('');$('game-count').textContent=`${rows.length} games shown · Most recent first · Regular season only`}
function players(){const key=$('metric').value,rows=[...data.players].sort((a,b)=>b[key]-a[key]);$('leaders').innerHTML=rows.slice(0,6).map((p,i)=>`<div class="leader"><span class="rank">0${i+1}</span><span>${p.name==='Shai Gilgeous-Alexander'?'S. Gilgeous-Alexander':p.name}</span><div class="bar-track"><div class="bar-fill" style="width:${p[key]/rows[0][key]*100}%"></div></div><b>${fixed(p[key])}</b></div>`).join('');const filtered=rows.filter(p=>p.name.toLowerCase().includes($('search').value.toLowerCase()));$('roster').innerHTML=filtered.length?filtered.map(p=>`<tr><td>${p.name}</td>${['games','minutes','points','rebounds','assists','steals','blocks','fg'].map(k=>`<td>${k==='games'?p[k]:fixed(p[k])}${k==='fg'?'%':''}</td>`).join('')}</tr>`).join(''):'<tr><td colspan="9">No players match your search.</td></tr>'}
function compare(){const a=data.players[+$('playerA').value],b=data.players[+$('playerB').value];$('compare').innerHTML=[['points','POINTS'],['rebounds','REBOUNDS'],['assists','ASSISTS'],['minutes','MINUTES'],['fg','FG %']].map(([k,l])=>`<div class="comparison"><b>${fixed(a[k])}</b><span>${l}</span><b>${fixed(b[k])}</b></div>`).join('')}
fetch('data.json').then(r=>{if(!r.ok)throw Error('Data unavailable');return r.json()}).then(d=>{data=d;['playerA','playerB'].forEach(id=>$(id).innerHTML=d.players.map((p,i)=>`<option value="${i}">${p.name}</option>`).join(''));$('playerB').value='1';team();players();compare();['month','venue'].forEach(id=>$(id).addEventListener('change',team));$('result').addEventListener('change',games);$('metric').addEventListener('change',players);$('search').addEventListener('input',players);['playerA','playerB'].forEach(id=>$(id).addEventListener('change',compare));$('reset').onclick=()=>{$('month').value='all';$('venue').value='All venues';$('result').value='all';team()}}).catch(e=>{$('kpis').textContent='Unable to load the dataset. Please reload the page.';console.error(e)});document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelector('nav .active')?.classList.remove('active');a.classList.add('active')}));
